/bin/bash -lc 'set -eu
scratch=$(mktemp -d "$PWD/.catalog-review.XXXXXX")
trap '"'python3 -c \"import shutil,sys; shutil.rmtree(sys.argv[1])\" \""'$scratch"'"' EXIT
(
  cd catalog
  npm_config_cache=\""'$scratch/npm-cache" npm_config_update_notifier=false npm test
)
REVIEW_SCRATCH="$scratch" node --input-type=module <<'"'NODE'
import { spawnSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
const modulePath = new URL('./catalog/src/catalog.mjs', import.meta.url).href;
const child = (code, ...args) => {
  const program = 'import {loadCatalog,setPinned,saveCatalog} from ' + JSON.stringify(modulePath) + '; ' + code;
  const result = spawnSync(process.execPath, ['--input-type=module', '-e', program, ...args], { encoding: 'utf8' });
  if (result.status "'!== 0) throw new Error(result.stderr || String(result.error));
  return JSON.parse(result.stdout);
};
const fixture = JSON.parse(readFileSync('"'./catalog/fixture/catalog.json', 'utf8'));
const duplicates = [
  { id: 'first', title: 'Shared', pinned: false },
  { id: 'target', title: 'Shared', pinned: false },
  { id: 'last', title: 'Other', pinned: true },
];
const checks = [
  { name: 'pin', cards: fixture, id: 'a', pinned: true },
  { name: 'unpin', cards: fixture, id: 'b', pinned: false },
  { name: 'duplicate-pin', cards: duplicates, id: 'target', pinned: true },
  { name: 'duplicate-unpin', cards: duplicates.map(card => ({ ...card, pinned: true })), id: 'target', pinned: false },
  { name: 'legacy', cards: [{ id: 'legacy', title: 'Old' }, ...fixture], id: 'a', pinned: true },
  { name: 'missing', cards: fixture, id: 'missing', pinned: true },
];
const read = path => child('console.log(JSON.stringify(loadCatalog(process.argv[1])));', path);
for (const { name, cards, id, pinned } of checks) {
  const path = join(process.env.REVIEW_SCRATCH, name + '.json');
  writeFileSync(path, JSON.stringify(cards));
  const originalFile = readFileSync(path, 'utf8');
  const before = read(path);
  const edit = child("'`
    const [path,id,raw] = process.argv.slice(1);
    const cards = loadCatalog(path);
    let changed;
    try { changed = setPinned(cards, id, JSON.parse(raw)); }
    catch (error) { console.log(JSON.stringify({error: error.message})); }
    if (changed) {
      saveCatalog(path, changed);
      console.log(JSON.stringify({saved: true}));
    }
  `, path, id, String(pinned));
  const disk = JSON.parse(readFileSync(path, '"'utf8'));
  const reopened = read(path);
  const expected = cards.map(card => ({
    ...card, pinned: card.id === id ? pinned : (card.pinned ?? false),
  }));
  console.log(JSON.stringify({ name, before, edit, disk, reopened, expected,
    matches: JSON.stringify(reopened) === JSON.stringify(expected),
    fileUnchanged: originalFile === readFileSync(path,'utf8') }));
}
NODE
find catalog -type f -print0 | sort -z | xargs -0 sha256sum | sha256sum
sha256sum intake/*"

